#include <iostream>
#include <string>
#include <algorithm>
#include <cstdio>

struct RGBv { float r,g,b; };

int main(int argc, char** argv){
    float r=0.4f,g=0.2f,b=0.8f;
    if (argc>3){ r=std::stof(argv[1]); g=std::stof(argv[2]); b=std::stof(argv[3]); }
    float mx = std::max(std::max(r,g),b);
    float mn = std::min(std::min(r,g),b);
    float d  = mx-mn;
    // hue
    float h;
    if (mx==mn) h=0.0f;
    else if (mx==r && g>=b) h = 60.0f*(g-b)/d;
    else if (mx==r)         h = 60.0f*(g-b)/d + 360.0f;
    else if (mx==g)         h = 60.0f*(b-r)/d + 120.0f;
    else                    h = 60.0f*(r-g)/d + 240.0f;
    // hsl
    float l = (mx+mn)/2.0f;
    float sl;
    if (mx==mn) sl=0.0f;
    else if (l<0.5f) sl = d/(mx+mn);
    else             sl = d/(2.0f-mx-mn);
    // hsv
    float sv = (mx==0.0f)?0.0f:(d/mx);
    float v  = mx;
    // cmyk
    float k = 1.0f-mx;
    float c,m,y;
    if (k==1.0f){ c=0.0f;m=0.0f;y=0.0f; }
    else { c=(1.0f-r-k)/(1.0f-k); m=(1.0f-g-k)/(1.0f-k); y=(1.0f-b-k)/(1.0f-k); }
    // yuv
    float yy = 0.299f*r + 0.587f*g + 0.114f*b;
    float uu = -0.147f*r - 0.289f*g + 0.436f*b;
    float vv = 0.615f*r - 0.515f*g - 0.100f*b;
    std::cout << h << " " << sl << " " << l << " "
              << h << " " << sv << " " << v << " "
              << c << " " << m << " " << y << " " << k << " "
              << yy << " " << uu << " " << vv << std::endl;
    return 0;
}
EOF
