#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
static uint64_t s=0x243F6A8885A308D3ULL;
static uint64_t nx(){ s^=s<<13; s^=s>>7; s^=s<<17; return s; }
static float pick(int mode){
    uint32_t u=(uint32_t)nx();
    switch(mode){
      case 0: return (float)(nx()%1000001)/1000000.0f;              // uniform [0,1] 1e-6 grid
      case 1: { float f; uint32_t b=u; b=(b&0x807FFFFFu)|(((u>>9)%60+100)<<23); memcpy(&f,&b,4); return f; } // random exp
      case 2: return (float)((int64_t)(nx()%4000001)-2000000)/1000000.0f; // [-2,2]
      case 3: { int k=nx()%13; const float v[13]={0.f,-0.f,1.f,-1.f,0.5f,2.f,255.f,1e-6f,1e6f,0.25f,0.75f,1.f/3.f,3.4028235e38f}; return v[k]; }
      case 4: { // near-tie: base value +- few ulp
              float base=(float)(nx()%1001)/1000.0f; uint32_t bb; memcpy(&bb,&base,4);
              bb += (uint32_t)((int)(nx()%9)-4); memcpy(&base,&bb,4); return base; }
      default: { float f; uint32_t b=u&0x7FFFFFFFu; if(((b>>23)&0xFF)==0xFF) b&=0x7F7FFFFFu; memcpy(&f,&b,4); if(nx()&1) f=-f; return f; }
    }
}
int main(int argc,char**argv){
    long n=atol(argv[1]); int base=atoi(argv[2]);
    for(long i=0;i<n;i++){
        int mode = (base>=0)? base : (int)(nx()%6);
        float a=pick(mode),b=pick(mode),c=pick(mode);
