        if(std::fpclassify(a)==FP_SUBNORMAL||std::fpclassify(b)==FP_SUBNORMAL||std::fpclassify(c)==FP_SUBNORMAL){i--;continue;}
        printf("%.9g %.9g %.9g\n",a,b,c);
    }
}
