    pub exp10: i64,
}

impl Dec {
    pub fn zero() -> Self {
        Dec { digits: Vec::new(), exp10: 0 }
    }

    /// Normalising constructor.  `exp10` saturates rather than overflowing so
    /// that absurd literals such as `1e999999999999999999999` stay well
    /// defined (they are out of range either way).
    pub fn new(digits: Vec<u8>, exp10: i64) -> Self {
        let mut digits = digits;
        let first = digits.iter().position(|&d| d != b'0');
        match first {
            None => Dec::zero(),
            Some(start) => {
                digits.drain(..start);
                let mut trailing = 0i64;
                while digits.len() > 1 && *digits.last().unwrap() == b'0' {
                    digits.pop();
                    trailing += 1;
                }
                Dec { digits, exp10: exp10.saturating_add(trailing) }
            }
        }
    }

    pub fn is_zero(&self) -> bool {
        self.digits.is_empty()
    }

    /// Decimal exponent of the leading digit: the value is
    /// `d.ddd... * 10^magnitude()`.  Only meaningful for non-zero values.
    pub fn magnitude(&self) -> i64 {
        self.digits.len() as i64 - 1 + self.exp10
    }

    /// Compare two non-negative decimals.
    pub fn cmp_value(&self, other: &Dec) -> Ordering {
        match (self.is_zero(), other.is_zero()) {
            (true, true) => return Ordering::Equal,
            (true, false) => return Ordering::Less,
            (false, true) => return Ordering::Greater,
            _ => {}
        }
        match self.magnitude().cmp(&other.magnitude()) {
            Ordering::Equal => {}
            ord => return ord,
        }
        // Same leading position: compare digit by digit, treating a shorter
        // digit string as zero-padded on the right.
        let n = self.digits.len().max(other.digits.len());
        for i in 0..n {
            let a = *self.digits.get(i).unwrap_or(&b'0');
            let b = *other.digits.get(i).unwrap_or(&b'0');
            match a.cmp(&b) {
                Ordering::Equal => {}
                ord => return ord,
            }
        }
        Ordering::Equal
    }
}

/// The exact value of `|f32::from_bits(bits)|` as a [`Dec`].
///
/// The caller must have ruled out infinities and NaNs.
pub fn exact_decimal_f32(bits: u32) -> Dec {
    let exp_field = (bits >> 23) & 0xFF;
    let frac = bits & 0x007F_FFFF;
    // |v| == mantissa * 2^exp2, exactly.
    let (mantissa, exp2) = if exp_field == 0 {
        (frac as u64, -149i32)
    } else {
        ((frac | 0x0080_0000) as u64, exp_field as i32 - 150)
    };
    if mantissa == 0 {
        return Dec::zero();
    }
    let mut n = BigUint::from_u64(mantissa);
    if exp2 >= 0 {
        n.mul_pow2(exp2 as u32);
        Dec::new(n.to_digits(), 0)
    } else {
        // m * 2^-k == (m * 5^k) * 10^-k
        n.mul_pow5((-exp2) as u32);
        Dec::new(n.to_digits(), exp2 as i64)
    }
}

/// The exact value of `mantissa * 2^exp2` as a [`Dec`].
pub fn exact_decimal_dyadic(mantissa: &BigUint, exp2: i64) -> Dec {
    if mantissa.is_zero() {
        return Dec::zero();
    }
    let mut n = mantissa.clone();
    if exp2 >= 0 {
        n.mul_pow2(exp2 as u32);
        Dec::new(n.to_digits(), 0)
    } else {
        n.mul_pow5((-exp2) as u32);
        Dec::new(n.to_digits(), exp2)
    }
}

