//! `std::cout << some_float` with default stream flags.
//!
//! With `defaultfloat` formatting and the stream's default precision of 6, the
//! C++ standard defines the conversion as `printf("%.*g", 6, (double)value)`.
//! Since the value being printed is an `f32`, widening to `double` is exact, so
//! the whole job is `%.6g` of a float.
//!
//! `%g` with precision `P`:
//!
//! 1. round the value to `P` significant decimal digits;
//! 2. let `X` be the decimal exponent **of the rounded value** — rounding
//!    `9.99999949e-8` up to `1.00000e-7` moves the exponent, and the style
//!    decision must see the new one;
//! 3. use `%e` when `X < -4 || X >= P`, otherwise `%f` with `P - 1 - X` decimals;
//! 4. strip trailing zeros from the fraction, and the `.` if nothing is left.
//!
//! Rounding is round-half-to-even applied to the *exact* value, which is what
//! glibc does.  `1.015625f` — exactly `1.015625` — prints as `1.01562`, and
//! `1.046875f` prints as `1.04688`; a half-up rule gets the first one wrong and
//! `f64` arithmetic cannot see the tie at all.

use crate::colorspace::decimal::exact_decimal_f32;

/// The default `std::ostream` precision.
const PRECISION: usize = 6;

/// Formats `v` exactly as `std::cout << v` would.
pub fn fmt_float(v: f32) -> String {
    let bits = v.to_bits();
    let negative = bits >> 31 != 0;
    let exp_field = (bits >> 23) & 0xFF;
    let frac = bits & 0x007F_FFFF;

    // glibc prints the sign of a NaN, and the C++ program can reach one: a
    // `-nan` argument survives `stof`, and `inf - inf` produces the x86 "real
    // indefinite" QNaN, whose sign bit is set.
    if exp_field == 0xFF {
        return match (frac != 0, negative) {
            (true, true) => "-nan".to_string(),
            (true, false) => "nan".to_string(),
            (false, true) => "-inf".to_string(),
            (false, false) => "inf".to_string(),
        };
    }
    if exp_field == 0 && frac == 0 {
        return if negative { "-0".to_string() } else { "0".to_string() };
    }

    let dec = exact_decimal_f32(bits);
    let digits = &dec.digits;

    // Decimal exponent of the leading digit, before rounding.
    let mut exp10 = dec.magnitude();

    // Round the exact expansion to PRECISION significant digits.
    let mut head: Vec<u8> = if digits.len() <= PRECISION {
        let mut h = digits.clone();
        h.resize(PRECISION, b'0');
        h
    } else {
        let mut h = digits[..PRECISION].to_vec();
        let tail = &digits[PRECISION..];
        let round_up = match tail[0] {
            d if d > b'5' => true,
            d if d < b'5' => false,
            // Leading 5: a tie only if nothing follows it, else round up.
            _ if tail[1..].iter().any(|&d| d != b'0') => true,
            // Exact tie — round to even.
            _ => (h[PRECISION - 1] - b'0') % 2 == 1,
        };
        if round_up {
            let mut i = PRECISION;
            let mut carry = true;
            while carry && i > 0 {
                i -= 1;
                if h[i] == b'9' {
                    h[i] = b'0';
                } else {
                    h[i] += 1;
                    carry = false;
                }
            }
            if carry {
                // 999999 + 1 -> 1000000: keep PRECISION digits, shift exponent.
                h[0] = b'1';
                for d in h[1..].iter_mut() {
                    *d = b'0';
                }
                exp10 += 1;
            }
        }
        h
    };
    // `head` now holds exactly PRECISION significant digits and the value is
    // `head[0].head[1..] * 10^exp10`.
    debug_assert_eq!(head.len(), PRECISION);
    debug_assert_ne!(head[0], b'0');

    let mut out = String::with_capacity(16);
    if negative {
        out.push('-');
    }

    if exp10 < -4 || exp10 >= PRECISION as i64 {
        // Scientific style with PRECISION - 1 fraction digits, zeros stripped.
        let mut end = head.len();
        while end > 1 && head[end - 1] == b'0' {
            end -= 1;
        }
        out.push(head[0] as char);
        if end > 1 {
            out.push('.');
            push_ascii(&mut out, &head[1..end]);
        }
        out.push('e');
        out.push(if exp10 < 0 { '-' } else { '+' });
        let abs_exp = exp10.unsigned_abs();
        if abs_exp < 10 {
            out.push('0');
        }
        out.push_str(&abs_exp.to_string());
    } else if exp10 >= 0 {
        // Fixed style, at least one integer digit.
        let int_len = exp10 as usize + 1; // <= PRECISION because exp10 < PRECISION
        let mut end = head.len();
        while end > int_len && head[end - 1] == b'0' {
            end -= 1;
        }
        push_ascii(&mut out, &head[..int_len]);
        if end > int_len {
            out.push('.');
            push_ascii(&mut out, &head[int_len..end]);
        }
    } else {
        // Fixed style, value below 1: "0." then -exp10 - 1 zeros then the digits.
        let mut end = head.len();
        while end > 1 && head[end - 1] == b'0' {
            end -= 1;
        }
        out.push_str("0.");
        for _ in 0..(-exp10 - 1) {
            out.push('0');
        }
        push_ascii(&mut out, &head[..end]);
    }

    // Keep the allocation from being reported as unused when debug_assert is off.
    head.clear();
    out
}

fn push_ascii(out: &mut String, bytes: &[u8]) {
    for &b in bytes {
        out.push(b as char);
    }
}

