        h
    };
    // `head` now holds exactly PRECISION significant digits and the value is
    // `head[0].head[1..] * 10^exp10`.
    debug_assert_eq!(head.len(), PRECISION);
    debug_assert_ne!(head[0], b'0');

    let mut out = String::with_capacity(16);
    if negative {
        out.push('-');
    }

    if exp10 < -4 || exp10 >= PRECISION as i64 {
        // Scientific style with PRECISION - 1 fraction digits, zeros stripped.
        let mut end = head.len();
