            end -= 1;
        }
        out.push(head[0] as char);
        if end > 1 {
            out.push('.');
            push_ascii(&mut out, &head[1..end]);
        }
        out.push('e');
        out.push(if exp10 < 0 { '-' } else { '+' });
        let abs_exp = exp10.unsigned_abs();
        if abs_exp < 10 {
            out.push('0');
        }
        out.push_str(&abs_exp.to_string());
    } else if exp10 >= 0 {
        // Fixed style, at least one integer digit.
        let int_len = exp10 as usize + 1; // <= PRECISION because exp10 < PRECISION
        let mut end = head.len();
        while end > int_len && head[end - 1] == b'0' {
            end -= 1;
        }
        push_ascii(&mut out, &head[..int_len]);
        if end > int_len {
            out.push('.');
            push_ascii(&mut out, &head[int_len..end]);
        }
    } else {
        // Fixed style, value below 1: "0." then -exp10 - 1 zeros then the digits.
        let mut end = head.len();
        while end > 1 && head[end - 1] == b'0' {
            end -= 1;
        }
        out.push_str("0.");
        for _ in 0..(-exp10 - 1) {
            out.push('0');
        }
        push_ascii(&mut out, &head[..end]);
    }

    // Keep the allocation from being reported as unused when debug_assert is off.
    head.clear();
    out
}

fn push_ascii(out: &mut String, bytes: &[u8]) {
    for &b in bytes {
        out.push(b as char);
    }
}

