//! `std::stof`.
//!
//! libstdc++ implements it as a thin wrapper over glibc's `strtof`:
//!
//! ```c++
//! errno = 0;
//! float v = strtof(str, &end);
//! if (end == str) throw std::invalid_argument("stof");
//! if (errno == ERANGE) throw std::out_of_range("stof");
//! return v;
//! ```
//!
//! so this module has to reproduce three separate things: which prefix of the
//! string `strtof` consumes, the correctly rounded value of that prefix, and
//! when glibc raises `ERANGE`.
//!
//! The `ERANGE` rules were established by probing the reference binary and are
//! subtler than "the result did not fit":
//!
//! * **Overflow** — set whenever the correctly rounded result is infinite.
//!   `3.4028235677973366e38` (a hair under the FLT_MAX/2^128 midpoint) is fine;
//!   `3.4028236e38` is not.
//! * **Underflow** — glibc first rounds the significand to 24 bits with an
//!   *unbounded* exponent.  Only if that still lands below `2^-126` does it
//!   take the denormal path, and only then does an inexact result raise
//!   `ERANGE`.  This explains two otherwise baffling observations:
//!   `0x1p-149` succeeds (exact, so no flag) while the equal-valued `1e-45`
//!   fails, and `1.17549432e-38` succeeds while the smaller `1.17549431e-38`
//!   fails — the former rounds up to `2^-126` before the check happens.
//!
//! The unbounded-exponent rounding boundary is `2^-126 - 2^-151`, the midpoint
//! between `2^-126` and the largest 24-bit significand below it; exactly at the
//! midpoint, ties-to-even rounds up to the normal `2^-126`.

use std::cmp::Ordering;

use crate::colorspace::decimal::{exact_decimal_dyadic, exact_decimal_f32, BigUint, Dec};

/// Which C++ exception `stof` would have thrown.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// `std::invalid_argument` — `strtof` consumed nothing.
    InvalidArgument,
    /// `std::out_of_range` — `strtof` set `ERANGE`.
    OutOfRange,
}

impl StofError {
    /// The exception's fully qualified C++ type name.
    pub fn exception_name(self) -> &'static str {
        match self {
            StofError::InvalidArgument => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
}

/// Beyond this many significant hex digits (157 bits) a value can no longer be
/// an exact `f32`, so the tail is folded into a sticky bit.  Rounding is
/// unaffected and the value is flagged inexact, which is correct.
const MAX_HEX_SIGNIFICANT: usize = 40;

/// `std::stof(s)`.
pub fn stof(s: &str) -> Result<f32, StofError> {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    // strtof skips leading whitespace per the C locale's isspace().
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let sign_start = i;
    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    if let Some(v) = parse_infinity(bytes, i, negative) {
        return Ok(v);
    }
    if let Some(v) = parse_nan(bytes, i, negative) {
        return Ok(v);
    }
    if starts_hex_prefix(bytes, i) {
        return parse_hex(bytes, i + 2, negative);
    }
    parse_decimal(s, bytes, sign_start, i, negative)
}

fn eq_ignore_case(bytes: &[u8], at: usize, word: &[u8]) -> bool {
    bytes.len() >= at + word.len()
        && bytes[at..at + word.len()]
            .iter()
            .zip(word)
            .all(|(a, b)| a.to_ascii_lowercase() == *b)
}

fn parse_infinity(bytes: &[u8], at: usize, negative: bool) -> Option<f32> {
    // glibc matches "inf", then optionally extends it to "infinity"; the
    // returned value is the same either way, so only the match matters here.
    if eq_ignore_case(bytes, at, b"inf") {
        Some(if negative { f32::NEG_INFINITY } else { f32::INFINITY })
    } else {
        None
    }
}

fn parse_nan(bytes: &[u8], at: usize, negative: bool) -> Option<f32> {
    if !eq_ignore_case(bytes, at, b"nan") {
        return None;
    }
    // An optional "(n-char-sequence)" supplies the payload; glibc reads it with
    // strtoull(.., 0) and drops it into the mantissa. It never changes how the
    // value prints, but reproduce it anyway.
    let mut payload: u32 = 0;
    let mut j = at + 3;
    if bytes.get(j) == Some(&b'(') {
        let start = j + 1;
        let mut k = start;
        while k < bytes.len() && (bytes[k].is_ascii_alphanumeric() || bytes[k] == b'_') {
            k += 1;
        }
        if bytes.get(k) == Some(&b')') {
            if let Ok(text) = std::str::from_utf8(&bytes[start..k]) {
                payload = parse_c_integer(text).unwrap_or(0) & 0x003F_FFFF;
            }
            j = k + 1;
        }
    }
    let _ = j;
    let bits = 0x7FC0_0000u32 | payload | if negative { 0x8000_0000 } else { 0 };
    Some(f32::from_bits(bits))
}

/// `strtoull(text, .., 0)`: base 16 with a `0x` prefix, base 8 with a leading
/// `0`, base 10 otherwise.  Only the low bits survive, so wrapping is fine.
fn parse_c_integer(text: &str) -> Option<u32> {
    let (radix, body) = if let Some(rest) = text.strip_prefix("0x").or_else(|| text.strip_prefix("0X")) {
        (16, rest)
    } else if text.len() > 1 && text.starts_with('0') {
        (8, &text[1..])
    } else {
        (10, text)
    };
    if body.is_empty() {
        return None;
    }
    let mut acc: u32 = 0;
    for c in body.chars() {
        let d = c.to_digit(radix)?;
        acc = acc.wrapping_mul(radix).wrapping_add(d);
    }
    Some(acc)
}

fn starts_hex_prefix(bytes: &[u8], at: usize) -> bool {
    // "0x" only introduces a hex float when at least one hex digit follows,
    // possibly after the radix point.  Otherwise strtof consumes just the "0",
    // which is why "0x" and "0xg" both parse as zero.
    if bytes.get(at) != Some(&b'0') {
        return false;
    }
    if !matches!(bytes.get(at + 1), Some(b'x') | Some(b'X')) {
        return false;
    }
    let mut j = at + 2;
    let mut seen = false;
    while j < bytes.len() && bytes[j].is_ascii_hexdigit() {
        seen = true;
        j += 1;
    }
    if bytes.get(j) == Some(&b'.') {
        j += 1;
        while j < bytes.len() && bytes[j].is_ascii_hexdigit() {
            seen = true;
            j += 1;
        }
    }
    seen
}

fn parse_hex(bytes: &[u8], at: usize, negative: bool) -> Result<f32, StofError> {
    let mut mantissa = BigUint::zero();
    let mut significant = 0usize;
    let mut truncated = false;
    // Binary exponent contributed by digits dropped on the right, either
    // because they are fractional or because they exceeded the sticky window.
    let mut exp2: i64 = 0;

    let mut push = |mantissa: &mut BigUint, digit: u8, fractional: bool, significant: &mut usize, truncated: &mut bool, exp2: &mut i64| {
        if *significant == 0 && digit == 0 {
            // Leading zero: contributes nothing, but a fractional one still
            // shifts the exponent.
            if fractional {
                *exp2 -= 4;
            }
            return;
        }
        if *significant < MAX_HEX_SIGNIFICANT {
            mantissa.push_hex_digit(digit);
            *significant += 1;
            if fractional {
                *exp2 -= 4;
            }
        } else {
            *truncated = true;
            if !fractional {
                *exp2 += 4;
            }
        }
    };

    let mut j = at;
    while j < bytes.len() && bytes[j].is_ascii_hexdigit() {
        push(&mut mantissa, hex_val(bytes[j]), false, &mut significant, &mut truncated, &mut exp2);
        j += 1;
    }
    if bytes.get(j) == Some(&b'.') {
        j += 1;
        while j < bytes.len() && bytes[j].is_ascii_hexdigit() {
            push(&mut mantissa, hex_val(bytes[j]), true, &mut significant, &mut truncated, &mut exp2);
            j += 1;
        }
    }

    // Optional binary exponent. glibc accepts a hex float without one.
    if matches!(bytes.get(j), Some(b'p') | Some(b'P')) {
        let mut k = j + 1;
        let mut neg = false;
        match bytes.get(k) {
            Some(b'-') => {
                neg = true;
                k += 1;
            }
            Some(b'+') => k += 1,
            _ => {}
        }
        if bytes.get(k).map_or(false, |c| c.is_ascii_digit()) {
            let mut value: i64 = 0;
            while k < bytes.len() && bytes[k].is_ascii_digit() {
                value = value.saturating_mul(10).saturating_add((bytes[k] - b'0') as i64);
                if value > 1_000_000 {
                    value = 1_000_000; // any larger is already out of range
                }
                k += 1;
            }
            exp2 = exp2.saturating_add(if neg { -value } else { value });
        }
    }

    if truncated {
        // Fold everything dropped into a sticky low bit so that rounding still
        // sees "there was more".
        mantissa.push_hex_digit(1);
        exp2 -= 4;
    }

    if mantissa.is_zero() {
        return Ok(if negative { -0.0 } else { 0.0 });
    }

    let exact = exact_decimal_dyadic(&mantissa, exp2);
    finish(exact, negative)
}

fn hex_val(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        _ => c - b'A' + 10,
    }
}

fn parse_decimal(
    s: &str,
    bytes: &[u8],
    sign_start: usize,
    at: usize,
    negative: bool,
) -> Result<f32, StofError> {
    let mut digits: Vec<u8> = Vec::new();
    let mut exp10: i64 = 0;
    let mut any_digit = false;

    let mut j = at;
    while j < bytes.len() && bytes[j].is_ascii_digit() {
        digits.push(bytes[j]);
        any_digit = true;
        j += 1;
    }
    if bytes.get(j) == Some(&b'.') {
        j += 1;
        while j < bytes.len() && bytes[j].is_ascii_digit() {
            digits.push(bytes[j]);
            exp10 -= 1;
            any_digit = true;
            j += 1;
        }
    }
    if !any_digit {
        // Nothing usable: "", "+", ".", ".e3", "abc" all land here.
        return Err(StofError::InvalidArgument);
    }
    let mantissa_end = j;

    // An exponent is only consumed when it is complete; "1e+" parses as "1".
    let mut end = mantissa_end;
    if matches!(bytes.get(j), Some(b'e') | Some(b'E')) {
        let mut k = j + 1;
        let mut neg = false;
        match bytes.get(k) {
            Some(b'-') => {
                neg = true;
                k += 1;
            }
            Some(b'+') => k += 1,
            _ => {}
        }
        if bytes.get(k).map_or(false, |c| c.is_ascii_digit()) {
            let mut value: i64 = 0;
            while k < bytes.len() && bytes[k].is_ascii_digit() {
                value = value.saturating_mul(10).saturating_add((bytes[k] - b'0') as i64);
                if value > 1_000_000_000 {
                    value = 1_000_000_000;
                }
                k += 1;
            }
            exp10 = exp10.saturating_add(if neg { -value } else { value });
            end = k;
        }
    }

    // Rust's own float parser is correctly rounded and returns an infinity on
    // overflow rather than an error, which is exactly strtof's value contract.
    // Hand it precisely the text strtof would have consumed.
    let text = &s[sign_start..end];
    let value: f32 = text.parse().map_err(|_| StofError::InvalidArgument)?;
    let _ = value;

    let exact = Dec::new(digits, exp10);
    finish_with_value(exact, negative, text)
}

fn finish_with_value(exact: Dec, negative: bool, text: &str) -> Result<f32, StofError> {
    let value: f32 = text.parse().unwrap_or(if negative { -0.0 } else { 0.0 });
    check_range(exact, value)
}

/// Round a `Dec` to `f32` and apply glibc's `ERANGE` rules.
fn finish(exact: Dec, negative: bool) -> Result<f32, StofError> {
    // Rendering the exact decimal back to text and letting the standard library
    // round it keeps a single, known-correct rounding implementation in play.
    let mut text = String::with_capacity(exact.digits.len() + 24);
    if negative {
        text.push('-');
    }
    if exact.is_zero() {
        text.push('0');
    } else {
        for &d in &exact.digits {
            text.push(d as char);
        }
        text.push('e');
        text.push_str(&exact.exp10.to_string());
    }
    let value: f32 = text.parse().unwrap_or(if negative { -0.0 } else { 0.0 });
    check_range(exact, value)
}

/// `exact` is the requested magnitude, `value` the correctly rounded result.
fn check_range(exact: Dec, value: f32) -> Result<f32, StofError> {
    if value.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    if exact.is_zero() {
        return Ok(value); // a literal zero is not an underflow
    }

    let magnitude = value.abs();
    let denormal_path = if magnitude < f32::MIN_POSITIVE {
        true
    } else if magnitude == f32::MIN_POSITIVE {
        // Ambiguous band: the result is 2^-126 either because the value really
        // was normal, or because the 24-bit unbounded rounding pulled it up.
        exact.cmp_value(&unbounded_rounding_threshold()) == Ordering::Less
    } else {
        false
    };

    if denormal_path && exact_decimal_f32(magnitude.to_bits()) != exact {
        return Err(StofError::OutOfRange);
    }
    Ok(value)
}

/// `2^-126 - 2^-151`, the midpoint below `FLT_MIN` in the 24-bit significand
/// grid.  A magnitude at or above it rounds to a normal number before glibc
/// decides whether it underflowed.
fn unbounded_rounding_threshold() -> Dec {
    // 2^-126 - 2^-151 == (2^25 - 1) * 2^-151
    exact_decimal_dyadic(&BigUint::from_u64((1u64 << 25) - 1), -151)
}

/// Reproduce what happens when the exception escapes `main`: libstdc++'s
/// terminate handler prints the type and `what()` to stderr, then `abort()`
/// raises `SIGABRT` (shell exit status 134).
pub fn terminate_with(err: StofError) -> ! {
    eprint!(
        "terminate called after throwing an instance of '{}'\n  what():  stof\n",
        err.exception_name()
    );
    std::process::abort()
}

