    }
    if acc.truncated {
        // Fold everything dropped into a sticky low bit so that rounding still
        // sees "there was more" below the retained digits.
        acc.digits.push_hex_digit(1);
        acc.exp2 -= 4;
    }

    finish(exact_decimal_dyadic(&acc.digits, acc.exp2), negative)
}

/// Accumulates a hex significand, keeping at most [`MAX_HEX_SIGNIFICANT`]
/// significant digits and remembering whether anything was dropped.
#[derive(Default)]
struct HexMantissa {
    digits: BigUint2,
    significant: usize,
    truncated: bool,
    /// Binary exponent contributed by digit placement alone.
    exp2: i64,
}

impl HexMantissa {
    fn push(&mut self, digit: u8, fractional: bool) {
        if self.significant == 0 && digit == 0 {
            // A leading zero adds no precision, but a fractional one still
            // moves the radix point.
            if fractional {
                self.exp2 -= 4;
            }
            return;
        }
        if self.significant < MAX_HEX_SIGNIFICANT {
            self.digits.push_hex_digit(digit);
            self.significant += 1;
            if fractional {
                self.exp2 -= 4;
            }
        } else {
            self.truncated = true;
            if !fractional {
                self.exp2 += 4;
            }
        }
    }
}

/// `BigUint` with a `Default`, so `HexMantissa` can derive one.
type BigUint2 = BigUint;

fn hex_val(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        _ => c - b'A' + 10,
    }
}

/// Reads a `[eEpP][+-]?digits` exponent starting at the marker character.
/// Returns the signed value and the index just past it, or `None` when the
/// exponent is incomplete — `strtof` then leaves the marker unconsumed, which
/// is why `"1e+"` parses as `1`.
fn read_exponent(bytes: &[u8], marker: usize) -> Option<(i64, usize)> {
    let mut k = marker + 1;
    let mut neg = false;
    match bytes.get(k) {
        Some(b'-') => {
            neg = true;
            k += 1;
        }
        Some(b'+') => k += 1,
        _ => {}
    }
    if !bytes.get(k).map_or(false, |c| c.is_ascii_digit()) {
        return None;
    }
    let mut value: i64 = 0;
    while k < bytes.len() && bytes[k].is_ascii_digit() {
        // Clamp well beyond anything that can still round to a finite f32;
        // this only has to preserve the sign and "astronomically large".
        value = (value.saturating_mul(10).saturating_add((bytes[k] - b'0') as i64)).min(1 << 40);
        k += 1;
    }
    Some((if neg { -value } else { value }, k))
}

