//! Exact decimal arithmetic.
//!
//! A finite binary float is a dyadic rational, so it has a *finite* exact
//! decimal expansion.  Two separate pieces of C++ behaviour hinge on that
//! expansion, which is why it lives here rather than in either caller:
//!
//! * `printf("%g")` rounds the **exact** value to six significant digits and
//!   breaks exact ties to even.  Ties really do occur — `1.015625f` prints as
//!   `1.01562`, not `1.01563` — so the rounding cannot be done in `f64`.
//! * `strtof` reports `ERANGE` on underflow only when the conversion was
//!   *inexact*: `0x1p-149` succeeds while `1e-45`, the same float, fails.
//!   Deciding that needs an exact comparison between the requested value and
//!   the delivered one.

use std::cmp::Ordering;

/// Number of decimal digits held in one limb.
const LIMB_DIGITS: u32 = 9;
/// Radix of a limb; chosen so that limb * 5^13 + carry still fits in a `u64`.
const BASE: u64 = 1_000_000_000;

/// Minimal big unsigned integer, little-endian base-`BASE` limbs.
///
/// Only the operations the two callers need are implemented: multiply by a
/// small constant, and render to decimal digits.
#[derive(Clone, Debug)]
pub struct BigUint {
    limbs: Vec<u32>,
}

impl BigUint {
    pub fn zero() -> Self {
        BigUint { limbs: Vec::new() }
    }

    pub fn from_u64(mut v: u64) -> Self {
        let mut limbs = Vec::new();
        while v > 0 {
            limbs.push((v % BASE) as u32);
            v /= BASE;
        }
        BigUint { limbs }
    }

    pub fn is_zero(&self) -> bool {
        self.limbs.is_empty()
    }

    /// `self = self * m + add`, for `m` and `add` small enough that
    /// `(BASE - 1) * m + add` fits in a `u64`.
    fn mul_add_small(&mut self, m: u32, add: u32) {
        if self.limbs.is_empty() {
            if add != 0 {
                *self = BigUint::from_u64(add as u64);
            }
            return;
        }
        let mut carry = add as u64;
        for limb in self.limbs.iter_mut() {
            let cur = *limb as u64 * m as u64 + carry;
            *limb = (cur % BASE) as u32;
            carry = cur / BASE;
        }
        while carry > 0 {
            self.limbs.push((carry % BASE) as u32);
            carry /= BASE;
        }
    }

    /// `self *= 16; self += digit` — used to accumulate a hex mantissa.
    pub fn push_hex_digit(&mut self, digit: u8) {
        self.mul_add_small(16, digit as u32);
    }

    /// `self *= 2^n`.
    pub fn mul_pow2(&mut self, mut n: u32) {
        if self.is_zero() {
            return;
        }
        // 2^29 is the largest power of two with (BASE - 1) * 2^29 < u64::MAX.
        while n >= 29 {
            self.mul_add_small(1 << 29, 0);
            n -= 29;
        }
        if n > 0 {
            self.mul_add_small(1 << n, 0);
        }
    }

    /// `self *= 5^n`.
    pub fn mul_pow5(&mut self, mut n: u32) {
        if self.is_zero() {
            return;
        }
        // 5^13 = 1_220_703_125 is the largest power of five that still keeps
        // (BASE - 1) * 5^13 inside a u64.
        while n >= 13 {
            self.mul_add_small(1_220_703_125, 0);
            n -= 13;
        }
        if n > 0 {
            let mut p = 1u32;
            for _ in 0..n {
                p *= 5;
            }
            self.mul_add_small(p, 0);
        }
    }

    /// Decimal digits as ASCII, most significant first, without leading zeros.
    /// Zero renders as the empty vector.
    pub fn to_digits(&self) -> Vec<u8> {
        if self.limbs.is_empty() {
            return Vec::new();
        }
        let mut out = Vec::with_capacity(self.limbs.len() * LIMB_DIGITS as usize);
        let (top, rest) = self.limbs.split_last().unwrap();
        out.extend_from_slice(top.to_string().as_bytes());
        for limb in rest.iter().rev() {
            let s = limb.to_string();
            for _ in s.len()..LIMB_DIGITS as usize {
                out.push(b'0');
            }
            out.extend_from_slice(s.as_bytes());
        }
        out
    }
}

/// A finite non-negative decimal, `digits * 10^exp10`.
///
/// Always normalised: `digits` carries neither leading nor trailing zeros, and
/// zero is represented as an empty `digits` with `exp10 == 0`.  Normalising
/// makes equality and ordering trivial.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Dec {
    pub digits: Vec<u8>,
    pub exp10: i64,
}

impl Dec {
    pub fn zero() -> Self {
        Dec { digits: Vec::new(), exp10: 0 }
    }

    /// Normalising constructor.  `exp10` saturates rather than overflowing so
    /// that absurd literals such as `1e999999999999999999999` stay well
    /// defined (they are out of range either way).
    pub fn new(digits: Vec<u8>, exp10: i64) -> Self {
        let mut digits = digits;
        let first = digits.iter().position(|&d| d != b'0');
        match first {
            None => Dec::zero(),
            Some(start) => {
                digits.drain(..start);
                let mut trailing = 0i64;
                while digits.len() > 1 && *digits.last().unwrap() == b'0' {
                    digits.pop();
                    trailing += 1;
                }
                Dec { digits, exp10: exp10.saturating_add(trailing) }
            }
        }
    }

    pub fn is_zero(&self) -> bool {
        self.digits.is_empty()
    }

    /// Decimal exponent of the leading digit: the value is
    /// `d.ddd... * 10^magnitude()`.  Only meaningful for non-zero values.
    pub fn magnitude(&self) -> i64 {
        self.digits.len() as i64 - 1 + self.exp10
    }

    /// Compare two non-negative decimals.
    pub fn cmp_value(&self, other: &Dec) -> Ordering {
        match (self.is_zero(), other.is_zero()) {
            (true, true) => return Ordering::Equal,
            (true, false) => return Ordering::Less,
            (false, true) => return Ordering::Greater,
            _ => {}
        }
        match self.magnitude().cmp(&other.magnitude()) {
            Ordering::Equal => {}
            ord => return ord,
        }
        // Same leading position: compare digit by digit, treating a shorter
        // digit string as zero-padded on the right.
        let n = self.digits.len().max(other.digits.len());
        for i in 0..n {
            let a = *self.digits.get(i).unwrap_or(&b'0');
            let b = *other.digits.get(i).unwrap_or(&b'0');
            match a.cmp(&b) {
                Ordering::Equal => {}
                ord => return ord,
            }
        }
        Ordering::Equal
    }
}

/// The exact value of `|f32::from_bits(bits)|` as a [`Dec`].
///
/// The caller must have ruled out infinities and NaNs.
pub fn exact_decimal_f32(bits: u32) -> Dec {
    let exp_field = (bits >> 23) & 0xFF;
    let frac = bits & 0x007F_FFFF;
    // |v| == mantissa * 2^exp2, exactly.
    let (mantissa, exp2) = if exp_field == 0 {
        (frac as u64, -149i32)
    } else {
        ((frac | 0x0080_0000) as u64, exp_field as i32 - 150)
    };
    if mantissa == 0 {
        return Dec::zero();
    }
    let mut n = BigUint::from_u64(mantissa);
    if exp2 >= 0 {
        n.mul_pow2(exp2 as u32);
        Dec::new(n.to_digits(), 0)
    } else {
        // m * 2^-k == (m * 5^k) * 10^-k
        n.mul_pow5((-exp2) as u32);
        Dec::new(n.to_digits(), exp2 as i64)
    }
}

/// The exact value of `mantissa * 2^exp2` as a [`Dec`].
pub fn exact_decimal_dyadic(mantissa: &BigUint, exp2: i64) -> Dec {
    if mantissa.is_zero() {
        return Dec::zero();
    }
    let mut n = mantissa.clone();
    if exp2 >= 0 {
        n.mul_pow2(exp2 as u32);
        Dec::new(n.to_digits(), 0)
    } else {
        n.mul_pow5((-exp2) as u32);
        Dec::new(n.to_digits(), exp2)
    }
}

