//! The `ColorSpace` value types.
//!
//! Every channel is an `f32`, matching the C++ originals; see the crate docs
//! for the evidence that the reference implementation is single precision.

/// Red, green, blue. The nominal range is 0..=1, but nothing clamps, and the
/// reference binary happily converts values outside it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

/// Hue in degrees, saturation, lightness.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

/// Hue in degrees, saturation, value.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

/// Cyan, magenta, yellow, key (black).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

/// Luma and the two BT.601 chrominance channels.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }
}

impl Hsv {
    pub fn new(h: f32, s: f32, v: f32) -> Self {
        Hsv { h, s, v }
    }
}

impl Cmyk {
    pub fn new(c: f32, m: f32, y: f32, k: f32) -> Self {
        Cmyk { c, m, y, k }
    }
}

impl Yuv {
    pub fn new(y: f32, u: f32, v: f32) -> Self {
        Yuv { y, u, v }
    }
}

